date '+%F %T'; uptime -s; last -x -n 3 reboot shutdown | head -n 3; echo AER_correctable=$(journalctl -b 0 -k --no-pager | grep -c 'PCIe Bus Error: severity=Correctable'); echo Uncorrected_or_Fatal=$(journalctl -b 0 -k --no-pager | grep -ciE 'severity=(Uncorrected|Fatal)'); echo Xid_NVRM=$(journalctl -b 0 -k --no-pager | grep -ciE 'NVRM: Xid|GPU has fallen|GPU lost|uvm.*fatal'); journalctl -b 0 -k --no-pager | grep 'PCIe Bus Error' | awk '{print $5}' | sort | uniq -c; systemctl show ollama -p NRestarts; nvidia-smi --query-gpu=index,temperature.gpu,memory.used --format=csv,noheader; ollama ps | tail -n +2
